import { defaultKeymap, history, historyKeymap } from '@codemirror/commands'
import { markdown, markdownLanguage } from '@codemirror/lang-markdown'
import { syntaxHighlighting } from '@codemirror/language'
import type { Extension } from '@codemirror/state'
import { drawSelection, EditorView, keymap } from '@codemirror/view'
import { codeBlockLines } from './code-block-lines'
import { editorTheme, markdownHighlightStyle } from './theme'

export const baseExtensions: readonly Extension[] = [
  history(),
  drawSelection(),
  EditorView.lineWrapping,
  markdown({ base: markdownLanguage }),
  syntaxHighlighting(markdownHighlightStyle),
  codeBlockLines,
  keymap.of([...defaultKeymap, ...historyKeymap]),
  editorTheme,
  EditorView.contentAttributes.of({ 'aria-label': 'Document' }),
]
import { HighlightStyle } from '@codemirror/language'
import { EditorView } from '@codemirror/view'
import { tags } from '@lezer/highlight'

export const markdownHighlightStyle = HighlightStyle.define([
  {
    tag: tags.heading1,
    fontSize: '1.85em',
    fontWeight: '700',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: tags.heading2,
    fontSize: '1.5em',
    fontWeight: '650',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: tags.heading3,
    fontSize: '1.25em',
    fontWeight: '600',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: tags.heading4,
    fontSize: '1.1em',
    fontWeight: '600',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: [tags.heading5, tags.heading6],
    fontWeight: '600',
    color: 'var(--color-ink-muted)',
  },
  { tag: tags.strong, fontWeight: '700', color: 'var(--color-ink-strong)' },
  { tag: tags.emphasis, fontStyle: 'italic' },
  { tag: tags.strikethrough, textDecoration: 'line-through' },
  {
    tag: tags.monospace,
    fontFamily: 'var(--font-mono)',
    fontSize: '0.9em',
    backgroundColor: 'var(--color-code-bg)',
    borderRadius: '4px',
    padding: '0.1em 0.3em',
  },
  { tag: tags.link, color: 'var(--color-accent)' },
  { tag: tags.url, color: 'var(--color-accent-dim)' },
  { tag: tags.quote, color: 'var(--color-ink-muted)', fontStyle: 'italic' },
  { tag: tags.processingInstruction, color: 'var(--color-ink-faint)' },
  { tag: tags.labelName, color: 'var(--color-ink-faint)' },
  { tag: tags.contentSeparator, color: 'var(--color-ink-faint)' },
  { tag: tags.comment, color: 'var(--color-ink-faint)' },
])

export const editorTheme = EditorView.theme(
  {
    '&': {
      color: 'var(--color-ink)',
      backgroundColor: 'transparent',
      fontSize: '1.0625rem',
      minHeight: '60vh',
    },
    '&.cm-focused': { outline: 'none' },
    '.cm-scroller': {
      fontFamily: 'var(--font-sans)',
      lineHeight: '1.75',
    },
    '.cm-content': {
      padding: '0.5rem 0',
      caretColor: 'var(--color-ink-strong)',
    },
    '.cm-line': { padding: '0' },
    '.cm-cursor, .cm-dropCursor': {
      borderLeftColor: 'var(--color-ink-strong)',
      borderLeftWidth: '2px',
    },
    '.cm-selectionBackground, &.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground':
      { backgroundColor: 'var(--color-selection)' },
    '.cm-codeblock-line': {
      fontFamily: 'var(--font-mono)',
      fontSize: '0.9em',
      backgroundColor: 'var(--color-code-bg)',
      padding: '0 0.75rem',
    },
    '.cm-codeblock-line span': {
      backgroundColor: 'transparent',
      padding: '0',
      fontSize: 'inherit',
    },
  },
  { dark: true },
)
.cm-ai-suggestion {
  border-radius: 3px;
  background: rgb(255 255 255 / 0.025);
}

.cm-ai-suggestion.cm-ai-active {
  background: var(--color-active-suggestion);
}

.cm-ai-refine-failed {
  text-decoration: underline dotted var(--color-danger);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.cm-ai-deleted {
  color: var(--color-deleted);
  background: var(--color-deleted-bg);
  border-radius: 2px;
  text-decoration: line-through;
  text-decoration-color: color-mix(
    in srgb,
    var(--color-deleted) 70%,
    transparent
  );
}

.cm-ai-inserted,
.cm-ai-replacement ins {
  color: var(--color-inserted);
  background: var(--color-inserted-bg);
  border-radius: 2px;
  text-decoration: none;
  white-space: pre-wrap;
}

.cm-ai-inserted-separated {
  margin-left: 0.3em;
}

.cm-ai-replacement {
  margin: 0.2rem 0 0.9rem;
  padding: 0.35rem 0.75rem;
  border-left: 2px solid var(--color-inserted);
  border-radius: 0 6px 6px 0;
  background: var(--color-inserted-bg);
  color: var(--color-inserted);
  white-space: pre-wrap;
}

.cm-ai-replacement ins {
  background: transparent;
}

.cm-ai-target-preview {
  background: var(--color-target-preview);
  border-radius: 3px;
}

.cm-ai-pending,
.cm-ai-refining {
  border-radius: 3px;
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    transparent 38%,
    var(--color-shimmer) 50%,
    transparent 62%,
    transparent 100%
  );
  background-size: 300% 100%;
  animation: cm-ai-shimmer 1.8s linear infinite;
}

@keyframes cm-ai-shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cm-ai-pending,
  .cm-ai-refining {
    animation: none;
    background-image: none;
    background-color: var(--color-shimmer);
  }
}

.cm-ai-failed {
  text-decoration: underline wavy var(--color-danger);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.cm-ai-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.3rem 0 0.9rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--color-danger-border);
  border-radius: 8px;
  background: var(--color-danger-bg);
  color: var(--color-danger);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  line-height: 1.45;
}

.cm-ai-error-actions {
  display: flex;
  flex: none;
  gap: 0.4rem;
}

.cm-editor .cm-tooltip.cm-ai-bubble,
.cm-editor .cm-tooltip.cm-ai-card {
  border: 1px solid var(--color-border);
  border-radius: 10px;
  background: var(--color-surface);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  line-height: 1.4;
  box-shadow: 0 8px 28px rgb(0 0 0 / 0.45);
  animation: cm-ai-fade-in 120ms ease-out;
}

.cm-editor .cm-tooltip.cm-ai-bubble {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(26rem, 90vw);
  padding: 0.5rem;
}

.cm-editor .cm-tooltip.cm-ai-card {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  max-width: min(28rem, 90vw);
  padding: 0.4rem;
}

.cm-editor .cm-tooltip.cm-ai-card-hover {
  pointer-events: none;
  animation-delay: 160ms;
  animation-fill-mode: backwards;
}

@keyframes cm-ai-fade-in {
  from {
    opacity: 0;
  }
}

.cm-ai-bubble-actions,
.cm-ai-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.cm-ai-bubble-ask {
  display: flex;
}

.cm-ai-bubble-input {
  flex: 1;
  min-width: 0;
  padding: 0.4rem 0.65rem;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  background: rgb(255 255 255 / 0.04);
  color: var(--color-ink-strong);
  font: inherit;
}

.cm-ai-bubble-input::placeholder {
  color: var(--color-ink-faint);
}

.cm-ai-bubble-input:focus {
  outline: none;
  border-color: var(--color-accent-dim);
  box-shadow: 0 0 0 2px rgb(122 162 247 / 0.25);
}

.cm-ai-chip,
.cm-ai-button {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.65rem;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  background: transparent;
  color: var(--color-ink);
  font: inherit;
  cursor: pointer;
}

.cm-ai-chip:hover,
.cm-ai-button:hover {
  background: var(--color-surface-hover);
  color: var(--color-ink-strong);
}

.cm-ai-chip:focus-visible,
.cm-ai-button:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
}

.cm-ai-button:disabled {
  color: var(--color-ink-muted);
  cursor: default;
}

.cm-ai-button:disabled:hover {
  background-color: transparent;
}

.cm-ai-button[aria-busy="true"] {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    transparent 38%,
    var(--color-shimmer) 50%,
    transparent 62%,
    transparent 100%
  );
  background-size: 300% 100%;
  animation: cm-ai-shimmer 1.8s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .cm-ai-button[aria-busy="true"] {
    animation: none;
    background-image: none;
    background-color: var(--color-shimmer);
  }
}

.cm-ai-refine {
  display: flex;
}

.cm-ai-card-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.35rem 0.5rem;
  border: 1px solid var(--color-danger-border);
  border-radius: 8px;
  background: var(--color-danger-bg);
  color: var(--color-danger);
}

.cm-ai-kbd {
  margin-left: 0.5rem;
  color: var(--color-ink-faint);
  font: inherit;
  font-size: 0.75rem;
}

.cm-ai-rationale {
  margin: 0;
  padding: 0.15rem 0.35rem 0;
  color: var(--color-ink-muted);
}

.toast-in {
  animation: cm-ai-fade-in 160ms ease-out;
}
import { EditorState, type Extension } from '@codemirror/state'
import { EditorView } from '@codemirror/view'
import { baseExtensions } from './extensions'

type EditorViewOptions = {
  readonly parent: HTMLElement
  readonly doc: string
  readonly onChange: (doc: string) => void
  readonly extensions?: readonly Extension[]
}

export const createEditorView = ({
  parent,
  doc,
  onChange,
  extensions = [],
}: EditorViewOptions): EditorView =>
  new EditorView({
    parent,
    state: EditorState.create({
      doc,
      extensions: [
        ...baseExtensions,
        ...extensions,
        EditorView.updateListener.of((update) => {
          if (update.docChanged) onChange(update.state.doc.toString())
        }),
      ],
    }),
  })

