@import "@fontsource-variable/inter";
@import "@fontsource-variable/league-spartan";
@import "./editor/suggestions.css";

@theme static {
  --color-canvas: #0e1014;
  --color-ink: #d9dce3;
  --color-ink-strong: #f2f4f8;
  --color-ink-muted: #8b909d;
  --color-ink-faint: #565b69;
  --color-accent: #7aa2f7;
  --color-accent-dim: #5a78b4;
  --color-code-bg: rgb(255 255 255 / 0.06);
  --color-selection: rgb(122 162 247 / 0.28);
  --color-banner-bg: #2a2110;
  --color-banner-border: #6b5316;
  --color-banner-ink: #f0d8a0;
  --color-surface: #181b24;
  --color-surface-hover: rgb(255 255 255 / 0.07);
  --color-border: rgb(255 255 255 / 0.11);
  --color-deleted: #d98e8e;
  --color-deleted-bg: rgb(229 107 107 / 0.1);
  --color-inserted: #94cfa2;
  --color-inserted-bg: rgb(111 191 130 / 0.13);
  --color-shimmer: rgb(122 162 247 / 0.3);
