  text-decoration: underline wavy var(--color-danger);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.cm-ai-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.3rem 0 0.9rem;
