@theme static {
  --color-canvas: #141417;
  --color-surface: #1e1e22;
  --color-ink-strong: #f1f1f3;
  --color-ink: rgb(241 241 243 / 0.82);
  --color-ink-muted: rgb(241 241 243 / 0.6);
  --color-ink-faint: rgb(241 241 243 / 0.38);
  --color-accent: #e37545;
  --color-accent-soft: #f0a179;
  --color-danger: #f87171;

  --color-fill: rgb(241 241 243 / 0.06);
  --color-fill-hover: rgb(241 241 243 / 0.11);
  --color-code-bg: var(--color-surface);
  --color-selection: rgb(227 117 69 / 0.28);
  --color-accent-tint: rgb(227 117 69 / 0.12);
  --color-danger-tint: rgb(248 113 113 / 0.1);

  --font-sans: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
