import { HighlightStyle } from '@codemirror/language'
import { EditorView } from '@codemirror/view'
import { tags } from '@lezer/highlight'

export const markdownHighlightStyle = HighlightStyle.define([
  {
    tag: tags.heading1,
    fontSize: '1.85em',
    fontWeight: '700',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: tags.heading2,
    fontSize: '1.5em',
    fontWeight: '650',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: tags.heading3,
    fontSize: '1.25em',
    fontWeight: '600',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: tags.heading4,
    fontSize: '1.1em',
    fontWeight: '600',
    color: 'var(--color-ink-strong)',
  },
  {
    tag: [tags.heading5, tags.heading6],
    fontWeight: '600',
    color: 'var(--color-ink-muted)',
  },
  { tag: tags.strong, fontWeight: '700', color: 'var(--color-ink-strong)' },
  { tag: tags.emphasis, fontStyle: 'italic' },
  { tag: tags.strikethrough, textDecoration: 'line-through' },
  {
    tag: tags.monospace,
    fontFamily: 'var(--font-mono)',
    fontSize: '0.9em',
    backgroundColor: 'var(--color-code-bg)',
    borderRadius: '4px',
    padding: '0.1em 0.3em',
  },
  { tag: tags.link, color: 'var(--color-accent)' },
  { tag: tags.url, color: 'var(--color-accent-dim)' },
  { tag: tags.quote, color: 'var(--color-ink-muted)', fontStyle: 'italic' },
  { tag: tags.processingInstruction, color: 'var(--color-ink-faint)' },
  { tag: tags.labelName, color: 'var(--color-ink-faint)' },
  { tag: tags.contentSeparator, color: 'var(--color-ink-faint)' },
  { tag: tags.comment, color: 'var(--color-ink-faint)' },
])

export const editorTheme = EditorView.theme(
  {
    '&': {
      color: 'var(--color-ink)',
      backgroundColor: 'transparent',
      fontSize: '1.0625rem',
      minHeight: '60vh',
    },
    '&.cm-focused': { outline: 'none' },
    '.cm-scroller': {
      fontFamily: 'var(--font-sans)',
      lineHeight: '1.75',
    },
    '.cm-content': {
      padding: '0.5rem 0',
      caretColor: 'var(--color-ink-strong)',
    },
    '.cm-line': { padding: '0' },
    '.cm-cursor, .cm-dropCursor': {
      borderLeftColor: 'var(--color-ink-strong)',
      borderLeftWidth: '2px',
    },
    '.cm-selectionBackground, &.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground':
      { backgroundColor: 'var(--color-selection)' },
    '.cm-codeblock-line': {
      fontFamily: 'var(--font-mono)',
      fontSize: '0.9em',
      backgroundColor: 'var(--color-code-bg)',
      borderInline: '0.75rem solid transparent',
    },
    '.cm-codeblock-line span': {
      backgroundColor: 'transparent',
      padding: '0',
      fontSize: 'inherit',
    },
  },
  { dark: true },
)

import { useEffect } from 'react'

const TOAST_DURATION_MS = 4500
const ACTION_TOAST_DURATION_MS = 12000

export type ToastMessage = {
  readonly id: number
  readonly text: string
  readonly action?: {
    readonly label: string
    readonly run: () => void
  }
}

type ToastProps = {
  readonly message: ToastMessage | null
  readonly onDismiss: () => void
}

export function Toast({ message, onDismiss }: ToastProps) {
  const id = message?.id
  const hasAction = message?.action !== undefined

  useEffect(() => {
    if (id === undefined) return undefined
    const timer = setTimeout(
      onDismiss,
      hasAction ? ACTION_TOAST_DURATION_MS : TOAST_DURATION_MS,
    )
    return () => clearTimeout(timer)
  }, [id, hasAction, onDismiss])

  return (
    <div
      role="status"
      aria-live="polite"
      className="pointer-events-none fixed inset-x-0 bottom-16 z-40 flex justify-center px-6"
    >
      {message ? (
        <p
          key={message.id}
          className="toast-in pointer-events-auto flex items-center gap-3 rounded-full border border-border bg-surface px-4 py-2 text-ink text-sm shadow-lg"
        >
          <span>{message.text}</span>
          {message.action ? (
            <button
              type="button"
              className="rounded-full border border-border px-2.5 py-0.5 text-ink-strong hover:bg-surface-hover focus-visible:outline-2 focus-visible:outline-accent focus-visible:outline-offset-1"
              onClick={() => {
                message.action?.run()
                onDismiss()
              }}
            >
              {message.action.label}
            </button>
          ) : null}
        </p>
      ) : null}
    </div>
  )
}

import { useEffect, useId, useRef, useState } from 'react'
import type { ReviewControls } from '../editor/review-controls'
import type { ReviewStatus } from '../editor/review-field'

type ReviewToolbarProps = {
  readonly status: ReviewStatus
  readonly controls: ReviewControls | null
}

const FOCUS_PLACEHOLDER = 'Focus (optional): tone, concision…'

const progressLabel = (added: number): string =>
  added === 0
    ? 'Reviewing…'
    : `Reviewing… ${added} ${added === 1 ? 'suggestion' : 'suggestions'}`

export function ReviewToolbar({ status, controls }: ReviewToolbarProps) {
  const [open, setOpen] = useState(false)
  const [focus, setFocus] = useState('')
  const rootRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const popoverId = useId()
  const wasRunning = useRef(false)

  useEffect(() => {
    if (
      wasRunning.current &&
      !status.running &&
      document.activeElement === document.body
    )
      triggerRef.current?.focus()
    wasRunning.current = status.running
  }, [status.running])

  useEffect(() => {
    if (open) inputRef.current?.focus()
  }, [open])

  useEffect(() => {
    if (!open) return undefined
    const onPointerDown = (event: PointerEvent): void => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const close = (): void => {
    setOpen(false)
    triggerRef.current?.focus()
  }

  const submit = (): void => {
    controls?.start(focus.trim())
    setFocus('')
    setOpen(false)
  }

  return (
    <div
      ref={rootRef}
      className="relative flex flex-wrap items-center justify-end gap-2 text-sm"
    >
      {status.open > 0 ? (
        <>
          <button
            type="button"
            className="cm-ai-button"
            onClick={() => controls?.acceptAll()}
          >
            Accept all
          </button>
          <button
            type="button"
            className="cm-ai-button"
            onClick={() => controls?.rejectAll()}
          >
            Reject all
          </button>
        </>
      ) : null}
      {status.running ? (
        <button
          type="button"
          className="cm-ai-button"
          aria-busy="true"
          title="Stop the Review pass"
          onClick={() => controls?.stop()}
        >
          {progressLabel(status.added)}
          <span className="ml-2 text-ink-strong">Stop</span>
        </button>
      ) : (
        <button
          ref={triggerRef}
          type="button"
          className="cm-ai-button"
          aria-haspopup="dialog"
          aria-expanded={open}
          aria-controls={open ? popoverId : undefined}
          disabled={controls === null}
          onClick={() => setOpen((value) => !value)}
        >
          Review
        </button>
      )}
      {open && !status.running ? (
        <form
          id={popoverId}
          role="dialog"
          aria-label="Review the Document"
          className="absolute top-full right-0 z-30 mt-2 flex w-[min(24rem,calc(100vw-3rem))] gap-2 rounded-xl border border-border bg-surface p-2 shadow-lg"
          onSubmit={(event) => {
            event.preventDefault()
            submit()
          }}
          onKeyDown={(event) => {
            if (event.key !== 'Escape') return
            event.preventDefault()
            event.stopPropagation()
            close()
          }}
        >
          <input
            ref={inputRef}
            type="text"
            className="cm-ai-bubble-input"
            placeholder={FOCUS_PLACEHOLDER}
            aria-label="Focus (optional)"
            autoComplete="off"
            spellCheck={false}
            value={focus}
            onChange={(event) => setFocus(event.target.value)}
          />
          <button type="submit" className="cm-ai-button">
            Review
          </button>
        </form>
      ) : null}
    </div>
  )
}

export function MissingKeyBanner() {
  return (
    <div
      role="status"
      className="fixed inset-x-0 bottom-0 z-50 border-banner-border border-t bg-banner-bg px-6 py-3 text-center text-banner-ink text-sm"
    >
      OpenRouter key missing. Add{' '}
      <code className="font-mono">OPENROUTER_API_KEY</code> to{' '}
      <code className="font-mono">.env</code> (see{' '}
      <code className="font-mono">.env.example</code>) and restart{' '}
      <code className="font-mono">pnpm dev</code>.
    </div>
  )
}

