  bubbleField,
  showTooltip.compute(
    [bubbleField, interactionField, 'selection', 'doc'],
    bubbleTooltip,
  ),
]
import { Prec } from '@codemirror/state'
import { keymap } from '@codemirror/view'
import { bubbleVisible, dismissBubbleEffect, openAskEffect } from './ask-bubble'
import { currentTarget } from './current-target'
import {
  closeRefineEffect,
  openRefineEffect,
  refineInputOpenFor,
} from './refine-input'
import {
  acceptAtCursor,
  type EditorHandle,
  rejectAtCursor,
} from './suggestion-commands'
import {
  activeAtCursor,
  cancelRefineEffect,
  suggestionAtCursor,
} from './suggestion-field'

const openAsk = (handle: EditorHandle): boolean => {
  if (currentTarget(handle.state) === undefined) return false
  handle.dispatch({ effects: openAskEffect.of(null) })
  return true
}

export const openAskOrRefine = (handle: EditorHandle): boolean => {
  const active = activeAtCursor(handle.state)
  if (active === undefined || !handle.state.selection.main.empty)
    return openAsk(handle)
  if (active.refine.status === 'working') return false
  handle.dispatch({ effects: openRefineEffect.of(active.id) })
  return true
}

const closeRefineInput = (handle: EditorHandle): boolean => {
  if (refineInputOpenFor(handle.state) === null) return false
  handle.dispatch({ effects: closeRefineEffect.of(null) })
  return true
}

const cancelRefineAtCursor = (handle: EditorHandle): boolean => {
  const found = suggestionAtCursor(handle.state)
  if (found?.status !== 'ready' || found.refine.status === 'idle') return false
  handle.dispatch({ effects: cancelRefineEffect.of(found.id) })
  return true
}

const dismissBubble = (handle: EditorHandle): boolean => {
  if (!bubbleVisible(handle.state)) return false
  handle.dispatch({ effects: dismissBubbleEffect.of(null) })
  return true
}

export const escapeAtCursor = (handle: EditorHandle): boolean =>
  dismissBubble(handle) ||
  closeRefineInput(handle) ||
  cancelRefineAtCursor(handle) ||
  rejectAtCursor(handle)

export const suggestionKeymap = Prec.highest(
  keymap.of([
    { key: 'Mod-k', run: openAskOrRefine, preventDefault: true },
    { key: 'Mod-Enter', run: acceptAtCursor },
    { key: 'Escape', run: escapeAtCursor },
  ]),
)
import type { Extension } from '@codemirror/state'
import { EditorView } from '@codemirror/view'
import type { ModelClient } from '../ai/client'
import type { SuggestionNotice } from '../suggestions/types'
import { askBubble } from './ask-bubble'
import { interactionState } from './interaction-state'
import { refineInputField } from './refine-input'
import {
  type ReviewStatus,
  reviewStatusOf,
  sameReviewStatus,
} from './review-field'
import {
  createReviewRuntime,
  type ReviewDrop,
  type ReviewNotice,
} from './review-runtime'
import { suggestionCards } from './suggestion-cards'
import { suggestionDecorations } from './suggestion-decorations'
import { suggestionsField, suggestionsOf } from './suggestion-field'
import { suggestionKeymap } from './suggestion-keymap'
import { createSuggestionRuntime } from './suggestion-runtime'

export type ReviewObserver = {
  readonly onStatus: (status: ReviewStatus) => void
  readonly onNotice: (notice: ReviewNotice) => void
  readonly onDrop?: (drop: ReviewDrop) => void
}

type SuggestionExtensionOptions = {
  readonly client: Pick<
    ModelClient,
    'requestSuggestion' | 'refineSuggestion' | 'reviewDocument'
  >
  readonly onNotice: (notice: SuggestionNotice) => void
  readonly review: ReviewObserver
}

export const suggestionExtensions = ({
  client,
  onNotice,
  review,
}: SuggestionExtensionOptions): readonly Extension[] => [
  suggestionsField,
  interactionState,
  askBubble,
  refineInputField,
  createSuggestionRuntime({ client }).extension,
  createReviewRuntime({
    client,
    onNotice: review.onNotice,
    onDrop: review.onDrop,
  }).extension,
  suggestionDecorations,
  suggestionCards,
  suggestionKeymap,
  EditorView.updateListener.of((update) => {
    const before = suggestionsOf(update.startState).notice
    const after = suggestionsOf(update.state).notice
    if (after && after.serial !== before?.serial) onNotice(after)
  }),
  EditorView.updateListener.of((update) => {
    const before = reviewStatusOf(update.startState)
    const after = reviewStatusOf(update.state)
    if (!sameReviewStatus(before, after)) review.onStatus(after)
  }),
]
type Child = Node | string

type Props = {
  readonly class?: string
  readonly attrs?: Readonly<Record<string, string>>
  readonly on?: {
    readonly [K in keyof HTMLElementEventMap]?: (
      event: HTMLElementEventMap[K],
    ) => void
  }
}

export const el = <K extends keyof HTMLElementTagNameMap>(
  tag: K,
  { class: className, attrs = {}, on = {} }: Props = {},
  children: readonly Child[] = [],
): HTMLElementTagNameMap[K] => {
  const node = document.createElement(tag)
  if (className) node.className = className
  for (const [name, value] of Object.entries(attrs)) {
    node.setAttribute(name, value)
  }
  for (const [name, handler] of Object.entries(on)) {
    node.addEventListener(name, handler as EventListener)
  }
  node.append(...children)
  return node
}

import { StateEffect, StateField } from '@codemirror/state'
import { type EditorView, ViewPlugin } from '@codemirror/view'
import type { SuggestionId } from '../suggestions/types'

export type InteractionState = {
  readonly pointerDown: boolean
  readonly focused: boolean
  readonly hoveredId: SuggestionId | null
}

export const pointerEffect = StateEffect.define<boolean>()
export const focusEffect = StateEffect.define<boolean>()
export const hoverEffect = StateEffect.define<SuggestionId | null>()

const applyInteraction = (
  state: InteractionState,
  effect: StateEffect<unknown>,
): InteractionState => {
  if (effect.is(pointerEffect)) return { ...state, pointerDown: effect.value }
  if (effect.is(focusEffect)) return { ...state, focused: effect.value }
  if (effect.is(hoverEffect)) return { ...state, hoveredId: effect.value }
  return state
}

export const interactionField = StateField.define<InteractionState>({
  create: () => ({ pointerDown: false, focused: false, hoveredId: null }),
  update: (value, transaction) =>
    transaction.effects.reduce(applyInteraction, value),
})

const suggestionIdOf = (target: EventTarget | null): SuggestionId | null =>
  target instanceof Element
    ? (target.closest<HTMLElement>('[data-suggestion-id]')?.dataset
        .suggestionId ?? null)
    : null

const interactionPlugin = ViewPlugin.define((view: EditorView) => {
  const setHover = (id: SuggestionId | null): void => {
    if (view.state.field(interactionField).hoveredId !== id)
      view.dispatch({ effects: hoverEffect.of(id) })
  }
  const onMouseDown = (): void =>
    view.dispatch({ effects: pointerEffect.of(true) })
  const onMouseUp = (): void => {
    if (view.state.field(interactionField).pointerDown)
      view.dispatch({ effects: pointerEffect.of(false) })
  }
  const onMouseOver = (event: MouseEvent): void =>
    setHover(suggestionIdOf(event.target))
  const onMouseLeave = (): void => setHover(null)
  const setFocused = (focused: boolean): void =>
    queueMicrotask(() => {
      if (
        view.dom.isConnected &&
        view.state.field(interactionField).focused !== focused
      )
        view.dispatch({ effects: focusEffect.of(focused) })
    })
  const onFocusIn = (): void => setFocused(true)
  const onFocusOut = (event: FocusEvent): void => {
    const next = event.relatedTarget
    if (!(next instanceof Node && view.dom.contains(next))) setFocused(false)
  }

  view.contentDOM.addEventListener('mousedown', onMouseDown)
  view.contentDOM.addEventListener('mouseover', onMouseOver)
  view.contentDOM.addEventListener('mouseleave', onMouseLeave)
  view.dom.addEventListener('focusin', onFocusIn)
  view.dom.addEventListener('focusout', onFocusOut)
  document.addEventListener('mouseup', onMouseUp)

  return {
    destroy: () => {
      view.contentDOM.removeEventListener('mousedown', onMouseDown)
      view.contentDOM.removeEventListener('mouseover', onMouseOver)
      view.contentDOM.removeEventListener('mouseleave', onMouseLeave)
      view.dom.removeEventListener('focusin', onFocusIn)
      view.dom.removeEventListener('focusout', onFocusOut)
      document.removeEventListener('mouseup', onMouseUp)
    },
  }
})

export const interactionState = [interactionField, interactionPlugin]
import type { EditorState } from '@codemirror/state'
import {
  type EditorView,
  showTooltip,
  type Tooltip,
  type TooltipView,
  type ViewUpdate,
} from '@codemirror/view'
import { describeError } from '../suggestions/error-message'
import { freeTextInstruction } from '../suggestions/instruction'
import { findSuggestion } from '../suggestions/state'
import type { ReadySuggestion, SuggestionId } from '../suggestions/types'
import { detectApplePlatform, formatShortcut } from '../ui/platform'
import { el } from './dom'
import { interactionField } from './interaction-state'
import {
  closeRefineEffect,
  openRefineEffect,
  refineInputOpenFor,
} from './refine-input'
import {
  acceptSuggestionById,
  rejectSuggestionById,
} from './suggestion-commands'
import {
  activeOf,
  cursorOf,
  suggestionsField,
  suggestionsOf,
} from './suggestion-field'
import { suggestionActionsFacet } from './suggestion-runtime'

type CardContent = {
  readonly suggestion: ReadySuggestion
  readonly showRationale: boolean
  readonly showActions: boolean
  readonly refineOpen: boolean
}

type CardKind = 'active' | 'hover'

const contentFor = (
  kind: CardKind,
  state: EditorState,
): CardContent | undefined => {
  const hoveredId = state.field(interactionField).hoveredId
  const active = activeOf(state)
  if (kind === 'active') {
    if (!active) return undefined
    const cursorInside =
      active.from <= cursorOf(state) && cursorOf(state) <= active.to
    return {
      suggestion: active,
      showRationale: cursorInside || hoveredId === active.id,
      showActions: true,
      refineOpen: refineInputOpenFor(state) === active.id,
    }
  }
  if (hoveredId === null || hoveredId === active?.id) return undefined
  const hovered = findSuggestion(suggestionsOf(state), hoveredId)
  return hovered?.status === 'ready'
    ? {
        suggestion: hovered,
        showRationale: true,
        showActions: false,
        refineOpen: false,
      }
    : undefined
}

const refineKey = ({ refine }: ReadySuggestion): string =>
  refine.status === 'failed'
    ? `failed:${describeError(refine.error)}`
    : refine.status

const contentKey = ({
  suggestion,
  showRationale,
  showActions,
  refineOpen,
}: CardContent): string =>
  [
    suggestion.id,
    suggestion.rationale,
    showRationale,
    showActions,
    refineOpen,
    refineKey(suggestion),
  ].join('\u0000')

const shortcutLabel = (key: string): string =>
  formatShortcut(key, detectApplePlatform())

type ButtonOptions = {
  readonly refocus?: boolean
  readonly disabled?: boolean
  readonly busy?: boolean
  readonly expanded?: boolean
}

const actionButton = (
  view: EditorView,
  label: string,
  hint: string | undefined,
  run: () => void,
  {
    refocus = true,
    disabled = false,
    busy = false,
    expanded,
  }: ButtonOptions = {},
) =>
  el(
    'button',
    {
      class: 'cm-ai-button',
      attrs: {
        type: 'button',
        ...(disabled && { disabled: '' }),
        ...(busy && { 'aria-busy': 'true' }),
        ...(expanded !== undefined && { 'aria-expanded': String(expanded) }),
      },
      on: {
        mousedown: (event) => event.preventDefault(),
        click: () => {
          run()
          if (refocus) view.focus()
        },
      },
    },
    hint === undefined
      ? [label]
      : [label, el('kbd', { class: 'cm-ai-kbd' }, [hint])],
  )

type RefineForm = {
  readonly form: HTMLFormElement
  readonly input: HTMLInputElement
}

const createRefineForm = (view: EditorView): RefineForm => {
  const input = el('input', {
    class: 'cm-ai-bubble-input',
    attrs: {
      type: 'text',
      placeholder: 'Refine: make it shorter…',
      'aria-label': 'Refine instruction',
      autocomplete: 'off',
      spellcheck: 'false',
    },
    on: {
      keydown: (event) => {
        if (event.key === 'Escape') {
          event.preventDefault()
          event.stopPropagation()
          input.value = ''
          view.dispatch({ effects: closeRefineEffect.of(null) })
          view.focus()
        } else if (event.key === 'k' && (event.metaKey || event.ctrlKey)) {
          event.preventDefault()
        }
      },
    },
  })
  const form = el(
    'form',
    {
      class: 'cm-ai-refine',
      on: {
        submit: (event) => {
          event.preventDefault()
          const id = refineInputOpenFor(view.state)
          const text = input.value.trim()
          if (id === null || text === '') return
          input.value = ''
          view.state
            .facet(suggestionActionsFacet)
            ?.refine(view, id, freeTextInstruction(text))
          view.focus()
        },
      },
    },
    [input],
  )
  return { form, input }
}

const refineButton = (
  view: EditorView,
  { suggestion, refineOpen }: CardContent,
) =>
  suggestion.refine.status === 'working'
    ? actionButton(view, 'Refining…', undefined, () => undefined, {
        disabled: true,
        busy: true,
      })
    : actionButton(
        view,
        'Refine',
        shortcutLabel('K'),
        () =>
          view.dispatch({
            effects: refineOpen
              ? closeRefineEffect.of(null)
              : openRefineEffect.of(suggestion.id),
          }),
        { refocus: refineOpen, expanded: refineOpen },
      )

const refineError = (
  view: EditorView,
  { refine, id }: ReadySuggestion,
  withRetry: boolean,
) =>
  refine.status === 'failed'
    ? [
        el('div', { class: 'cm-ai-card-error', attrs: { role: 'alert' } }, [
          el('span', { class: 'cm-ai-error-message' }, [
            describeError(refine.error),
          ]),
          ...(withRetry
            ? [
                actionButton(view, 'Retry', undefined, () =>
                  view.state
                    .facet(suggestionActionsFacet)
                    ?.retryRefine(view, id),
                ),
              ]
            : []),
        ]),
      ]
    : []

const renderCard = (
  view: EditorView,
  content: CardContent,
  { form }: RefineForm,
): Node[] => {
  const { suggestion, showRationale, showActions, refineOpen } = content
  return [
    ...(showRationale
      ? [el('p', { class: 'cm-ai-rationale' }, [suggestion.rationale])]
      : []),
    ...(showActions
      ? [
          el('div', { class: 'cm-ai-card-actions' }, [
            actionButton(view, 'Accept', shortcutLabel('↵'), () =>
              acceptSuggestionById(view, suggestion.id),
            ),
            actionButton(view, 'Reject', 'Esc', () =>
              rejectSuggestionById(view, suggestion.id),
            ),
            refineButton(view, content),
          ]),
          ...(refineOpen ? [form] : []),
        ]
      : []),
    ...refineError(view, suggestion, showActions),
  ]
}

const openedRefine = (update: ViewUpdate): boolean =>
  update.transactions.some((transaction) =>
    transaction.effects.some((effect) => effect.is(openRefineEffect)),
  )

const cardCreator =
  (kind: CardKind) =>
  (view: EditorView): TooltipView => {
    const refineForm = createRefineForm(view)
    const dom = el('div', {
      class: `cm-ai-card cm-ai-card-${kind}`,
      attrs:
        kind === 'active' ? { role: 'group', 'aria-label': 'Suggestion' } : {},
      on: {
        mousedown: (event) => {
          if (event.target !== refineForm.input) event.preventDefault()
        },
      },
    })
    let renderedKey = ''
    let formOwner: SuggestionId | null = null
    const syncFormOwner = (state: EditorState): void => {
      const next = refineInputOpenFor(state)
      if (next === formOwner) return
      formOwner = next
      refineForm.input.value = ''
    }
    const sync = (state: EditorState): void => {
      syncFormOwner(state)
      const content = contentFor(kind, state)
      if (!content) return
      const key = contentKey(content)
      if (key === renderedKey) return
      renderedKey = key
      const hadFocus =
        refineForm.input.ownerDocument.activeElement === refineForm.input
      dom.replaceChildren(...renderCard(view, content, refineForm))
      if (hadFocus && refineForm.form.isConnected) refineForm.input.focus()
    }
    sync(view.state)
    return {
      dom,
      update: (update) => {
        sync(update.state)
        if (openedRefine(update) && refineForm.form.isConnected)
          refineForm.input.focus()
      },
    }
  }

const createActiveCard = cardCreator('active')
const createHoverCard = cardCreator('hover')

const tooltipFor = (
  kind: CardKind,
  state: EditorState,
  create: (view: EditorView) => TooltipView,
): Tooltip | null => {
  const content = contentFor(kind, state)
  return content ? { pos: content.suggestion.from, above: true, create } : null
}

export const suggestionCards = showTooltip.computeN(
  [suggestionsField, interactionField, 'selection'],
  (state) => [
    tooltipFor('active', state, createActiveCard),
    tooltipFor('hover', state, createHoverCard),
  ],
)

