import type { Extension } from '@codemirror/state'
import { type EditorView, tooltips } from '@codemirror/view'

type Viewport = { readonly width: number; readonly height: number }

export type TooltipSpace = {
  readonly top: number
  readonly left: number
  readonly right: number
  readonly bottom: number
}

export const spaceBelow = (
  inset: number,
  viewport: Viewport,
): TooltipSpace => ({
  top: Math.max(0, inset),
  left: 0,
  right: viewport.width,
  bottom: viewport.height,
})

const viewportOf = (view: EditorView): Viewport => {
  const root = view.dom.ownerDocument.documentElement
  return { width: root.clientWidth, height: root.clientHeight }
}

export const tooltipSpaceBelow = (getInset: () => number): Extension =>
  tooltips({
    tooltipSpace: (view) => spaceBelow(getInset(), viewportOf(view)),
  })
import type { EditorState, Text } from '@codemirror/state'
import { type Block, extractBlocks } from '../blocks/extract-blocks'
import { resolveTarget, type Target } from '../blocks/target'

const textCache = new WeakMap<Text, string>()
const blockCache = new WeakMap<Text, readonly Block[]>()

export const textOf = (state: EditorState): string => {
  const cached = textCache.get(state.doc)
  if (cached !== undefined) return cached
  const text = state.doc.toString()
  textCache.set(state.doc, text)
  return text
}

export const blocksOf = (state: EditorState): readonly Block[] => {
  const cached = blockCache.get(state.doc)
  if (cached) return cached
  const blocks = extractBlocks(textOf(state))
  blockCache.set(state.doc, blocks)
  return blocks
}

export const currentTarget = (state: EditorState): Target | undefined => {
  const { from, to } = state.selection.main
  return resolveTarget(blocksOf(state), textOf(state), { from, to })
}
import { EditorState, type StateEffect } from '@codemirror/state'
import { describe, expect, it } from 'vitest'
import { quickActionInstruction } from '../suggestions/instruction'
import {
  askBubble,
  bubbleVisible,
  dismissBubbleEffect,
  openAskEffect,
  targetPreviewRange,
} from './ask-bubble'
import {
  focusEffect,
  interactionField,
  pointerEffect,
} from './interaction-state'
import { beginEffect, suggestionsField } from './suggestion-field'

const DOC = 'First paragraph here.\n\nSecond paragraph here.'

const create = (anchor: number, head = anchor): EditorState =>
  EditorState.create({
    doc: DOC,
    selection: { anchor, head },
    extensions: [suggestionsField, interactionField, askBubble],
  })

const apply = (
  state: EditorState,
  ...effects: readonly StateEffect<unknown>[]
): EditorState => state.update({ effects }).state

const focused = (state: EditorState): EditorState =>
  apply(state, focusEffect.of(true))

describe('selection bubble', () => {
  it('stays hidden without focus, with an empty selection, or on whitespace', () => {
    expect(bubbleVisible(create(2, 8))).toBe(false)
    expect(bubbleVisible(focused(create(2)))).toBe(false)
    expect(bubbleVisible(focused(create(21, 23)))).toBe(false)
  })

  it('shows for a non-empty selection while the editor is focused', () => {
    expect(bubbleVisible(focused(create(2, 8)))).toBe(true)
  })

  it('hides while the pointer is down and shows again on release', () => {
    const dragging = apply(focused(create(2, 8)), pointerEffect.of(true))
    expect(bubbleVisible(dragging)).toBe(false)
    expect(bubbleVisible(apply(dragging, pointerEffect.of(false)))).toBe(true)
  })

  it('stays dismissed for the same selection and returns when it changes', () => {
    const dismissed = apply(focused(create(2, 8)), dismissBubbleEffect.of(null))
    expect(bubbleVisible(dismissed)).toBe(false)
    expect(
      bubbleVisible(
        dismissed.update({ selection: { anchor: 2, head: 9 } }).state,
      ),
    ).toBe(true)
  })
